-- Keep the supplied original immutable; the SHA-256 identifies the exact DOCX.
-- Existing acceptances retain their original wording and do not gain consent
-- to the new document. The new version requires affirmative acceptance again.
alter table show_registration_private.policies
  add column document jsonb not null default '{}'::jsonb
  check (jsonb_typeof(document)='object');
alter table show_registration_private.acceptances
  add column document jsonb not null default '{}'::jsonb
  check (jsonb_typeof(document)='object');

update show_registration_private.policies
set version = 'hlsr-2027-indemnity-c3e23a4c4021',
    agreement = 'I have read and agree to the full 2027 Release of Liability and Indemnity linked above.',
    document = $indemnity${"title": "2027 Release of Liability and Indemnity", "url": "https://show.ringmasterone.com/documents/houston/2027-open-show-indemnity-c3e23a4c4021.docx", "sha256": "c3e23a4c402142841cf88b04f90541a70f5ae79e1c94d776b24c5ebc7f0a470d", "source_filename": "2027 Open Show Indemnity.docx", "text": "       2027 RELEASE OF LIABILITY AND INDEMNITY \n\n                                      As valid consideration for entry into and participation in activities (the “Activities”) associated with Houston Livestock Show and Rodeo, Inc., Houston Livestock Show and Rodeo Educational Fund, and Corral Club, LLC, (collectively, “HLSR”), the undersigned hereby enter into this RELEASE OF LIABILITY AND INDEMNITY AGREEMENT (this “Agreement”).\n\nINVITATIONAL SHOW: Activities related to the Houston Livestock Show are invitational and HLSR reserves the right to extend or withhold an invitation to any Exhibitor or Contestant. \n\nACKNOWLEDGMENT OF RISKS: The undersigned recognizes and understands that there are risks associated with the Exhibitor’s participation in the Activities including, but not limited to, bodily injury or death and theft, damage or destruction to property. UNDER CHAPTER 87, TEXAS CIVIL PRACTICE AND REMEDIES CODE, A FARM ANIMAL PROFESSIONAL OR FARM OWNER OR LESSEE IS NOT LIABLE FOR AN INJURY TO OR THE DEATH OF A PARTICIPANT IN FARM ANIMAL ACTIVITIES, INCLUDING AN EMPLOYEE OR INDEPENDENT CONTRACTOR, RESULTING FROM THE INHERENT RISKS OF FARM ANIMAL ACTIVITIES. UNDER CHAPTER 87, TEXAS CIVIL PRACTICE AND REMEDIES CODE, A LIVESTOCK SHOW SPONSOR IS NOT LIABLE FOR AN INJURY TO OR THE DEATH OF A PARTICIPANT IN A LIVESTOCK SHOW RESULTING FROM THE INHERENT RISKS OF LIVESTOCK SHOW ACTIVITIES.\n\nRELEASE FROM LIABILITY: The undersigned hereby RELEASES, ACQUITS AND FOREVER DISCHARGES HLSR, its subsidiaries and affiliates and its and their present and former directors, officers, employees, agents, volunteers, and representatives and the respective heirs, administrators, executors, successors and assigns (collectively, the “HLSR Parties” or individually, an “HLSR Party”) from any and all claims, causes of action, suits, demands, settlements, judgments, and/or expenses (including, but not limited to, reasonable attorneys’ fees) for personal injury, death and/or property damage, accrued or to accrue in the future, known or unknown, (collectively, “Claims”) relating to or arising out of any negligent acts occurring during the Exhibitor’s participation in the Activities, including but not limited to the NEGLIGENT ACTIONS OF THE HLSR PARTIES, REGARDLESS OF WHETHER SUCH NEGLIGENCE WAS THE SOLE, PROXIMATE OR PRODUCING CAUSE OF THE CLAIMS. Without limiting the foregoing, the undersigned agrees that the HLSR Parties shall not be liable to the Exhibitor, his/her family, heirs, administrators, executors or assigns for Claims arising from or related to the Exhibitor’s participation in the Activities.\n\nAGREEMENT TO DEFEND, INDEMNIFY AND HOLD HARMLESS: The undersigned agrees to DEFEND, INDEMNIFY and HOLD HARMLESS THE HLSR PARTIES from any and all Claims, including, but not limited to, Claims resulting from THE HLSR PARTIES’ OWN NEGLIGENCE, REGARDLESS OF WHETHER SUCH NEGLIGENCE WAS THE SOLE, PROXIMATE OR PRODUCING CAUSE OF THE CLAIMS; provided, however, that the duty of the undersigned to defend, indemnify and hold harmless the HLSR Parties shall extend only to Claims arising directly or indirectly from the Exhibitor’s participation in the Activities.\n\nAUTHORIZATION FOR USE OF NAME, IMAGE AND LIKENESS: The undersigned GRANTS PERMISSION for the Exhibitor to be PHOTOGRAPHED, VIDEOED, RECORDED and/or INTERVIEWED (the “Material”) in connection with the Activities. The undersigned understands that any such photographs, videos, recordings and/or interviews may be incorporated by HLSR in television, film, video, visual, graphic, printed and/or social media (the “Artwork”). The undersigned grants HLSR, on a gratis, royalty-free basis, the non-exclusive right to include the Material as part of the Artwork and to distribute, exhibit and otherwise exploit (and to authorize others to distribute, exhibit and otherwise exploit) the Artwork and its related advertising, publicity and promotion incorporating the Material throughout the world in perpetuity in all media and by all means, now known or hereafter developed.\n\nCONSENT TO RELEASE OF EDUCATION RECORDS. The undersigned understands and acknowledges that entry in the Activities may be facilitated through the participant’s school of record, which may be subject to the Family Educational Rights and Privacy Act, 20 U.S.C. §§ 1232g et seq. (“FERPA”). The undersigned hereby WAIVES the privacy rights guaranteed by the statute for the limited purposes outlined in this Agreement and CONSENTS to the participant’s school of record releasing records related to the participant that are necessary to complete the participant’s entry into the Activities, including, but not limited to: the student’s name, address, email address, telephone number, age, grade level, parent name, parent telephone number, parent email address, campus/district of enrollment and teacher name.\n\nTEXAS LAW AND ARBRITRATION: As further inducement to HLSR to permit the Exhibitor’s participation in the Activities, the undersigned represents that he/she thoroughly and completely understands the legal effect of this Agreement, that he/she is freely and voluntarily entering into this Agreement, and that no representations, promises or statements made by the HLSR Parties, or any agent, attorney or other representative of an HLSR Party has influenced the undersigned in causing him/her to sign this Agreement. The undersigned understands that this Agreement shall be binding on him/her and the Exhibitor’s heirs, executors, successors and assigns, that the Agreement will be governed by the laws of Texas, and that jurisdiction and venue for resolution of any dispute regarding this Agreement shall lie in a Texas State Court in Harris County, Texas. If any part of this Agreement is determined to be invalid or unenforceable, it does not affect the validity of the remainder of this Agreement. The undersigned agrees to the terms and conditions above and acknowledges receipt of this Agreement.\n\nThe undersigned certify that they have read, understand and will abide by all rules and regulations of the Houston Livestock Show and Rodeo, including, but not limited to, the Exhibitor Handbook. The undersigned represent that they thoroughly understand that this is a complete and final release and indemnity agreement, that they are voluntarily entering into this Agreement and that no representations, promises or statements made by any HLSR Party or any agent, attorney or other representative of any HLSR Party has influenced the undersigned in causing them to sign this Agreement.\n\nSignature – Exhibitor:_______________________________________________    Date: _________________   \n\nExhibitor Name Printed: _____________________________________________\n\nIf the person on whose behalf this Agreement is being executed is a minor, a parent or legal guardian must also execute this Agreement.\n\nSignature - Parent/Guardian: ___________________________________________       Date: ________________ \n\nParent/Guardian Name Printed: _________________________________________\n\nRELATIONSHIP TO MINOR: ________________________________________"}$indemnity$::jsonb
where owner_user_id='bca983ed-59ac-4615-a9a7-a2ce56d3d8e8'
  and club_id='48522136-118e-4860-aa46-1abb2d783809';

-- Preserve the current household and school validation. Older app versions
-- receive the original document through their existing handbook link too.
do $patch$
declare definition text; marker text;
begin
  definition:=pg_get_functiondef('show_registration_private.requirements(uuid)'::regprocedure);
  marker:=$anchor$'handbook_url',p.handbook_url,'website_url',p.website_url,'exhibitors',kids$anchor$;
  if (length(definition)-length(replace(definition,marker,'')))/length(marker)<>1 then
    raise exception 'Registration document return anchor changed';
  end if;
  execute replace(definition,marker,$replacement$'handbook_url',coalesce(nullif(p.document->>'url',''),p.handbook_url),
    'website_url',p.website_url,'document',p.document-'text','exhibitors',kids$replacement$);

  definition:=pg_get_functiondef('show_registration_private.save_requirements(uuid,text,boolean,jsonb)'::regprocedure);
  marker:=$anchor$insert into show_registration_private.acceptances(cart_id,accepted_by,version,agreement,handbook_url,website_url,cart_signature,school_snapshot)
  values(c.id,auth.uid(),p.version,p.agreement,p.handbook_url,p.website_url,show_registration_private.cart_signature(c.id),snapshot);$anchor$;
  if (length(definition)-length(replace(definition,marker,'')))/length(marker)<>1 then
    raise exception 'Registration acceptance snapshot anchor changed';
  end if;
  execute replace(definition,marker,$replacement$insert into show_registration_private.acceptances(cart_id,accepted_by,version,agreement,handbook_url,website_url,cart_signature,school_snapshot,document)
  values(c.id,auth.uid(),p.version,p.agreement,p.handbook_url,p.website_url,show_registration_private.cart_signature(c.id),snapshot,p.document);$replacement$);
end;
$patch$;
notify pgrst,'reload schema';
